fn solve(coins: Vec<i8>) -> i8 {
    // Sum might exceed the i8 range (−128..127), so we sum in a larger type.
    let sum: i16 = coins.iter().map(|&c| c as i16).sum();
    // Check if sum is strictly positive and divisible by 5.
    if sum > 0 && sum % 5 == 0 {
        // The result fits in i8 (0..100).
        (sum / 5) as i8
    } else {
        -1
    }
}

fn main() {
    let tests = vec![
        (vec![1, 2, 3, 4, 5], 3),    // sum=15, 15/5=3
        (vec![0, 0, 0, 0, 0], -1),   // sum=0, invalid
        (vec![5, 5, 5, 5, 5], 5),    // sum=25, 25/5=5
        (vec![1, 1, 1, 1, 2], -1),   // sum=6, not divisible by 5
        (vec![100, 100, 100, 100, 100], 100), // sum=500, 500/5=100
    ];

    for (input, expected) in tests {
        let result = solve(input.clone());
        println!("solve({:?}) = {}, expected {}", input, result, expected);
        assert_eq!(result, expected);
    }
}